def append_output_token_ids(
    self,
    token_ids: int | list[int],
) -> None:
    if isinstance(token_ids, int):
        self._output_token_ids.append(token_ids)
        self._all_token_ids.append(token_ids)
    else:
        self._output_token_ids.extend(token_ids)
        self._all_token_ids.extend(token_ids)

    self.update_block_hashes()

def update_block_hashes(self) -> None:
    """Compute block hashes for any new full blocks and append them."""
    if self._block_hasher is not None:
        self.block_hashes.extend(self._block_hasher(self))

def _remove_cached_block_hashes(
    self,
    block: KVCacheBlock,
) -> list[BlockHashWithGroupId]:
    block_hashes: list[BlockHashWithGroupId] = []
    if block.block_hash is not None:
        block_hashes.append(block.block_hash)
    block_hashes.extend(self.cached_block_hashes_by_block.pop(block.block_id, ()))
    if not block_hashes:
        return []

    removed_hashes: list[BlockHashWithGroupId] = []
    for block_hash in block_hashes:
        if (
            self.cached_block_hash_to_block.pop(block_hash, block.block_id)
            is not None
        ):
            removed_hashes.append(block_hash)
    block.reset_hash()
    return removed_hashes

def _insert_block_hash(
    self,
    block_hash_with_group_id: BlockHashWithGroupId,
    block: KVCacheBlock,
    num_tokens: int | None,
) -> None:
    if block.block_hash == block_hash_with_group_id:
        return

    if self.cached_block_hash_to_block.contain(
        block_hash_with_group_id, block.block_id
    ):
        return

    if block.block_hash is None:
        block.set_block_hash(block_hash_with_group_id, num_tokens=num_tokens)
    else:
        self.cached_block_hashes_by_block.setdefault(block.block_id, set()).add(
            block_hash_with_group_id
        )
    self.cached_block_hash_to_block.insert(block_hash_with_group_id, block)

def get_new_blocks(self, num_blocks: int) -> list[KVCacheBlock]:
    """Get new blocks from the free block pool.

    Note that we do not check block cache in this function.

    Args:
        num_blocks: The number of blocks to allocate.

    Returns:
        A list of new block.
    """
    if num_blocks > self.get_num_free_blocks():
        raise ValueError(f"Cannot get {num_blocks} free blocks from the pool")

    ret: list[KVCacheBlock] = self.free_block_queue.popleft_n(num_blocks)

    # In order to only iterate the list once, we duplicated code a bit
    if self.enable_caching:
        for block in ret:
            self._maybe_evict_cached_block(block)
            assert block.ref_cnt == 0
            block.ref_cnt += 1
            if self.metrics_collector:
                self.metrics_collector.on_block_allocated(block)
    else:
        for block in ret:
            assert block.ref_cnt == 0
            block.ref_cnt += 1
            if self.metrics_collector:
                self.metrics_collector.on_block_allocated(block)
    return ret

# (1) Segment-boundary tails. ``retention_interval``:
#   None -> dense (a tail at every ``alignment_tokens`` boundary);
#   0    -> no dense tails (only the replay boundary below);
#   >0   -> a tail once per ``retention_interval``-sized segment.
segment_tokens = (
    alignment_tokens
    if retention_interval is None
    else (None if retention_interval == 0 else retention_interval)
)
if segment_tokens is not None:
    per_segment = segment_tokens // block_size
    if need >= per_segment:
        # Every block is reachable; cache them all.
        return None
    for i in range(start_block, end_block):
        if i >= shift and (i - shift) % per_segment >= per_segment - need:
            mask[i - start_block] = True

# (2) Reachable-boundary tails: the replay boundary (``num_prompt - 1``,
# capped by ``get_computed_blocks``) and any shared-prefix junction. Both
# land before segments would cover them under sparse retention, so keep
# the ``need``-block tail ending on each boundary explicitly.
if retention_interval is not None:
    for boundary_tokens in reachable_boundaries:
        aligned = boundary_tokens // alignment_tokens * alignment_tokens
        end = aligned // block_size + shift
        for j in range(max(start_block, end - need), min(end_block, end)):
            mask[j - start_block] = True

def take_kv_cache_block_copies(
    self,
) -> tuple[list[KVCacheBlockCopy], list[KVCacheBlock]]:
    """Drain pending copies and return their retained endpoints."""
    pending_copies: list[tuple[KVCacheBlock, KVCacheBlock]] = []
    for mgr in self.coordinator.single_type_managers:
        pending_copies.extend(mgr.take_pending_cow_copies())
    copies = [
        KVCacheBlockCopy(
            src_block_id=source_block.block_id,
            dst_block_id=cow_block.block_id,
        )
        for source_block, cow_block in pending_copies
    ]
    retained_blocks = [block for pair in pending_copies for block in pair]
    return copies, retained_blocks

def _validate_prefix_cache_retention_interval(
    retention_interval: int | None,
    scheduler_block_size: int,
    kv_cache_config: KVCacheConfig,
) -> None:
    if retention_interval is None:
        return

    # Retention sparsifies sliding-window and Mamba (linear-attention)
    # checkpoints; full-attention and chunked-local groups cache densely and
    # ignore it (their hit granularity must stay fine).
    if not any(
        isinstance(g.kv_cache_spec, (SlidingWindowSpec, MambaSpec))
        for g in kv_cache_config.kv_cache_groups
    ):
        raise ValueError(
            "VLLM_PREFIX_CACHE_RETENTION_INTERVAL is set but this model has "
            "no sliding-window or Mamba KV cache group, so retention has no "
            "effect. Unset it (it only applies to sliding-window and Mamba "
            "attention)."
        )

    if retention_interval < 0 or retention_interval % scheduler_block_size != 0:
        raise ValueError(
            f"VLLM_PREFIX_CACHE_RETENTION_INTERVAL ({retention_interval}) "
            "must be non-negative and a multiple of scheduler_block_size "
            f"({scheduler_block_size})."
        )

    # registered by a chunk ending exactly at its last hash boundary.
    tail_boundary
    if last_cache_position < tail_boundary < request.num_prompt_tokens
    else 0,
    # Marconi shared-prefix junction, block-floored (a sub-block
    # junction's state is not separately cacheable): cache its state
    # so sibling requests sharing the prefix can reuse it.
    start + (request.shared_prefix_boundary - start) // block_size * block_size
    if start < request.shared_prefix_boundary < end
    else 0,
)
# Stop at the earliest mandatory position strictly inside the chunk.
end = min((s for s in stops if start < s < end), default=end)
return max(end - start, 0)

def _free_cow_retained_blocks(
    self, blocks: list[KVCacheBlock], fence_seq: int
) -> None:
    """Release CoW copy retentions, deferring their return to the block
    pool while the step that runs the copy may still be in flight.
    """
    if not self.defer_block_free or fence_seq <= self.processed_step_seq:
        self.kv_cache_manager.block_pool.free_blocks(blocks)
        return
    self.deferred_frees.append((fence_seq, blocks[::-1]))

# Zero GPU memory for freshly allocated cache blocks to prevent
# stale NaN/data from corrupting attention or SSM computation.
if scheduler_output.new_block_ids_to_zero:
    self._zero_block_ids(scheduler_output.new_block_ids_to_zero)
if scheduler_output.kv_cache_block_copies:
    copy_kv_cache_blocks_inplace(
        self.kv_caches,
        self.kv_cache_config.num_blocks,
        scheduler_output.kv_cache_block_copies,
    )

self.request_block_hasher: Callable[[Request], list[BlockHash]] | None = None
if vllm_config.cache_config.enable_prefix_caching or kv_connector is not None:
    caching_hash_fn = get_hash_fn_by_name(
        vllm_config.cache_config.prefix_caching_hash_algo
    )
    init_none_hash(caching_hash_fn)

    self.request_block_hasher = get_request_block_hasher(
        hash_block_size, caching_hash_fn
    )
